begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values
('11111111-1111-4111-8111-111111111111','owner@example.invalid',now()),
('22222222-2222-4222-8222-222222222222','other@example.invalid',now());
create temporary table fixture(key text primary key,id uuid);
grant all on fixture to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-111111111111","role":"authenticated"}',true);
insert into fixture values('brand',public.create_owner_workspace('Owner','Workflow brand','UTC','','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',true));
insert into fixture values('fact',public.create_brand_fact((select id from fixture where key='brand'),gen_random_uuid(),'product','Original fact','Source','','Team',current_date+30));
select throws_ok($$select public.create_opportunity((select id from fixture where key='brand'),gen_random_uuid(),'Title','Problem','Action','Uncertainty','Relevance','Product reference','small',(select id from fixture where key='fact'),1)$$,'22023',null,'Unapproved evidence cannot support opportunity');
select public.review_brand_fact((select id from fixture where key='brand'),(select id from fixture where key='fact'),1,'approved');
insert into fixture values('opportunity',public.create_opportunity((select id from fixture where key='brand'),'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','Title','Problem','Action','Uncertainty','Relevance','Product reference','small',(select id from fixture where key='fact'),2));
select is(public.create_opportunity((select id from fixture where key='brand'),'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','Title','Problem','Action','Uncertainty','Relevance','Product reference','small',(select id from fixture where key='fact'),2),(select id from fixture where key='opportunity'),'Creation retry is idempotent');
select throws_ok($$select public.update_opportunity((select id from fixture where key='brand'),(select id from fixture where key='opportunity'),1,'dismissed',2,'','','')$$,'22023',null,'Dismissal requires reason');
select throws_ok($$select public.update_opportunity((select id from fixture where key='brand'),(select id from fixture where key='opportunity'),1,'open',2,'22222222-2222-4222-8222-222222222222','','')$$,'22023',null,'Assignee must have current access');
select throws_ok($$select public.update_opportunity((select id from fixture where key='brand'),(select id from fixture where key='opportunity'),1,'snoozed',2,'','2000-01-01T00:00:00Z','')$$,'22023',null,'Past snooze rejected');
select lives_ok($$select public.update_opportunity((select id from fixture where key='brand'),(select id from fixture where key='opportunity'),1,'in_progress',1,auth.uid()::text,'','Started work')$$,'Owner can assign and start work');
select throws_ok($$select public.update_opportunity((select id from fixture where key='brand'),(select id from fixture where key='opportunity'),1,'open',2,'','','')$$,'40001',null,'Stale workflow mutation rejected');
select public.comment_opportunity((select id from fixture where key='brand'),(select id from fixture where key='opportunity'),'Evidence reviewed with product team');
select is((select count(*)::int from public.opportunity_events where event_type='comment'),1,'Comment persisted');
insert into fixture values('report',public.create_client_report((select id from fixture where key='brand'),'cccccccc-cccc-4ccc-8ccc-cccccccccccc','Report',current_date,current_date,'Known gaps'));
select is((select (snapshot->'coverage'->>'opportunities')::integer from public.client_reports),1,'Report captures selected denominator');
select ok((select snapshot->'analytics_days'='[]'::jsonb from public.client_reports),'Missing analytics has no fabricated measurement rows');
select public.save_brand_fact((select id from fixture where key='brand'),(select id from fixture where key='fact'),2,gen_random_uuid(),'product','Corrected fact','Source','','Team',current_date+30);
select ok((select evidence_needs_review from public.opportunities),'Fact correction flags dependent opportunity');
select throws_ok($$select public.update_opportunity((select id from fixture where key='brand'),(select id from fixture where key='opportunity'),3,'completed',1,'','','Done')$$,'22023',null,'Changed evidence blocks completion');
select is((select snapshot->'opportunities'->0->'evidence'->>'statement' from public.client_reports),'Original fact','Report does not change with later fact correction');
select throws_ok($$select public.refresh_opportunity_evidence((select id from fixture where key='brand'),(select id from fixture where key='opportunity'),3)$$,'22023',null,'Pending evidence cannot be acknowledged as approved');
select public.review_brand_fact((select id from fixture where key='brand'),(select id from fixture where key='fact'),3,'approved');
select public.refresh_opportunity_evidence((select id from fixture where key='brand'),(select id from fixture where key='opportunity'),3);
select ok((select not evidence_needs_review and fact_version=4 from public.opportunities),'Review records exact current fact version');
select public.update_opportunity((select id from fixture where key='brand'),(select id from fixture where key='opportunity'),4,'dismissed',1,'','','Not a current priority');
select public.update_opportunity((select id from fixture where key='brand'),(select id from fixture where key='opportunity'),5,'open',2,'','','Reopened');
select is((select details->>'reason' from public.opportunity_events where details->>'state'='dismissed'),'Not a current priority','Dismissal reason survives reopening');
select throws_ok($$update public.opportunities set priority=1$$,'42501',null,'Direct opportunity writes denied');
select throws_ok($$select public.create_client_report((select id from fixture where key='brand'),gen_random_uuid(),'Oversized',current_date-400,current_date,'')$$,'22023',null,'Unbounded date range rejected');
select set_config('request.jwt.claims','{"sub":"22222222-2222-4222-8222-222222222222","role":"authenticated"}',true);
select is((select count(*)::int from public.opportunities),0,'Unrelated tenant cannot list opportunities');
select is((select count(*)::int from public.client_reports),0,'Unrelated tenant cannot read snapshots');
select is((select count(*)::int from public.opportunity_events),0,'Unrelated tenant cannot inspect comments');
select throws_ok($$select public.comment_opportunity((select id from fixture where key='brand'),(select id from fixture where key='opportunity'),'Injected')$$,'42501',null,'Unrelated user cannot comment');
reset role;
select throws_ok($$update public.client_reports set annotation='tampered'$$,'42501',null,'Reports are immutable even for privileged callers');
select throws_ok($$delete from public.opportunity_events$$,'42501',null,'Activity cannot be erased');
update public.brand_memberships set active=false where user_id='11111111-1111-4111-8111-111111111111';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-111111111111","role":"authenticated"}',true);
select is((select count(*)::int from public.client_reports),0,'Revocation removes report read/export authority');
reset role;
select * from finish();
rollback;
